def normalize_residency_barangays(apps, schema_editor):
    ResidencyVerification = apps.get_model('api', 'ResidencyVerification')
    Barangay = apps.get_model('locations', 'Barangay')

    for verification in ResidencyVerification.objects.all().iterator():
        name = (verification.barangay_name or '').strip()
        if not name:
            verification.legacy_barangay_name = ''
            verification.save(update_fields=['legacy_barangay_name'])
            continue

        candidates = Barangay.objects.filter(
            name__iexact=name,
            city_municipality__name__iexact='Lucena City',
        )
        count = candidates.count()
        if count > 1:
            raise RuntimeError(
                f'Residency verification {verification.pk} has ambiguous barangay name '
                f'{name!r} in Lucena City; resolve duplicate barangays before migrating.'
            )
        if count == 1:
            verification.barangay_record_id = candidates.values_list('pk', flat=True).get()
            verification.legacy_barangay_name = ''
        else:
            verification.legacy_barangay_name = name
        verification.save(update_fields=['barangay_record', 'legacy_barangay_name'])


def restore_residency_barangay_names(apps, schema_editor):
    ResidencyVerification = apps.get_model('api', 'ResidencyVerification')

    for verification in ResidencyVerification.objects.select_related('barangay_record').iterator():
        verification.barangay_name = (
            verification.barangay_record.name
            if verification.barangay_record_id
            else verification.legacy_barangay_name
        )
        verification.save(update_fields=['barangay_name'])


